const raw = $input.first().json || {};
const data = raw.data || raw || {};
const edges = data.data || data.edges || data.items || data.results || [];

const leads = (Array.isArray(edges) ? edges : []).map((edge, idx) => {
  const node = edge.node || edge;
  const person = node.person || {};
  const company = node.company || person.company || {};
  const email = String(person.email || node.email || person.pointOfContact?.email || '').toLowerCase().trim();
  return {
    lead_id: `messenger-${Date.now()}-${idx}`,
    opportunity_id: node.id || '',
    person_id: person.id || '',
    company_id: company.id || '',
    full_name: person.name || person.displayName || '',
    email: email,
    company: company.name || node.companyName || '',
    role: person.jobTitle || '',
    campaign_id: node.campaign_id || node.customFields?.campaign_id || '',
    product_name: node.product_name || node.customFields?.product_name || '',
    stage: node.stage || 'NEW',
  };
}).filter(l => l.email && l.full_name);

return leads.map(l => ({ json: l }));

const raw = $input.first().json || {};
const yamlText = raw.data || raw.body || raw.yaml || JSON.stringify(raw);

function parseYaml(text) {
  const lines = text.split('\n');
  const result = {};
  let section = null;
  for (let line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    if (trimmed.startsWith('- ')) {
      const arrName = section || 'root';
      if (!result[arrName]) result[arrName] = [];
      result[arrName].push(trimmed.replace('- ', '').trim());
      continue;
    }
    if (line.startsWith('  ') && !line.startsWith('    ') && section) {
      const match = trimmed.match(/^([\w_]+):\s*(.*)$/);
      if (match) {
        if (!result[section]) result[section] = {};
        let val = match[2].trim();
        if (val.startsWith('"') && val.endsWith('"')) val = val.slice(1,-1);
        if (val === 'true') val = true;
        if (val === 'false') val = false;
        if (!isNaN(Number(val)) && val !== '') val = Number(val);
        result[section][match[1]] = val;
      }
      continue;
    }
    const match = trimmed.match(/^([\w_]+):\s*(.*)$/);
    if (match) {
      let val = match[2].trim();
      if (val === '') { section = match[1]; continue; }
      if (val.startsWith('"') && val.endsWith('"')) val = val.slice(1,-1);
      if (val === 'true') val = true;
      if (val === 'false') val = false;
      if (!isNaN(Number(val)) && val !== '') val = Number(val);
      result[match[1]] = val;
      section = null;
    }
  }
  return result;
}

let campaign = {};
try {
  campaign = parseYaml(yamlText);
} catch (e) {
  campaign = { _parse_error: e.message };
}

const lead = $('Split In Batches').item.json || {};
return [{ json: { ...lead, campaign } }];

const lead = $('Split In Batches').item.json || {};
const campaign = lead.campaign || {};
const product = campaign.product || {};

const inputText = [
  `LEAD: ${lead.full_name} - ${lead.role} en ${lead.company}`,
  `PRODUCTO: ${product.name || 'LEV Innovation'}`,
  `DESCRIPCIÓN: ${product.description || ''}`,
  `EMAIL DE: ${campaign.email?.from_name || 'LEV Innovation'}`,
  `ASUNTO BASE: ${campaign.email?.subject_template || ''}`,
  '',
  `Construye el email de outreach personalizado.`
].join('\n');

return [{ json: { ...lead, _agent_input: inputText } }];

const item = $input.first().json || {};
const raw = String(item.output || item.text || '').trim();
let parsed = {};

try {
  const match = raw.match(/{[\s\S]*}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  }
} catch (e) {
  parsed = { _parse_error: e.message };
}

const subject = parsed.subject || 'Conectemos — LEV Innovation';
const bodyHtml = parsed.body_html || `<p>${parsed.body_text || 'Hola, me gustaría conectar contigo.'}</p>`;
const bodyText = parsed.body_text || 'Hola, me gustaría conectar contigo.';

return [{ json: {
  ...item,
  email_subject: subject,
  email_body_html: bodyHtml,
  email_body_text: bodyText,
  _parse_error: parsed._parse_error || null,
} }];

